// Poulpy's pictures, by file name: his moods and poses are painted from the 3D model (design/poulpy-3d/pictures,
// generated by design/build-poulpy-pictures.mjs) and are transparent, so they sit on a light or a dark page; the
// loader is still a drawing, from design/poulpy (generated by design/build-poulpy.mjs).
const pictures = import.meta.glob<string>('../../../design/poulpy-3d/pictures/*.png', { eager: true, query: '?url', import: 'default' })
const loaders = import.meta.glob<string>('../../../design/poulpy/loader*.svg', { eager: true, query: '?url', import: 'default' })
const named = (files: Record<string, string>) =>
  Object.entries(files).map(([path, src]) => [path.slice(path.lastIndexOf('/') + 1, path.lastIndexOf('.')), src] as const)

export const poulpyDrawings = Object.fromEntries([...named(pictures), ...named(loaders)]) as Record<PoulpyDrawing, string>

export type PoulpyDrawing =
  | 'mood_proud' | 'mood_happy' | 'mood_recovering' | 'mood_annoyed' | 'mood_grumpy' | 'mood_fuming'
  | 'pose_champion' | 'pose_cocky' | 'pose_exhausted' | 'pose_fuming' | 'pose_patched_up' | 'pose_pouting'
  | 'pose_shy' | 'pose_side_glance' | 'pose_sleeping' | 'pose_standing_tall' | 'pose_straining' | 'pose_thinking'
  | 'loader' | 'loader_small'
